  function pop(anchor, build, at){ closePop(); const p = h('div', {class: 'pop', role: 'menu'}); build(p); document.body.appendChild(p);
    const r = at ? {left: at.x, right: at.x, bottom: at.y, top: at.y} : anchor.getBoundingClientRect(); const pw = p.offsetWidth, ph = p.offsetHeight; let x = Math.min(r.left, innerWidth - pw - 8), y = r.bottom + 4; if (y + ph > innerHeight - 8) y = Math.max(8, r.top - ph - 4);
    p.style.left = Math.max(8, x) + 'px'; p.style.top = y + 'px'; setTimeout(() => { const off = ev => { if (!p.contains(ev.target)){ p.remove(); document.removeEventListener('pointerdown', off, true); } }; document.addEventListener('pointerdown', off, true); }, 0); return p; }
